/bin/zsh -lc "cat > src/orchestration/chatOrchestrator.acceptance.test.ts <<'EOF'
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {createBedrockProvider} from '../providers/bedrock/bedrockProvider.js';
import type {ChatSession} from '../types/session.js';

// specs/hal-engine-config-hooks/spec.md#9
it('reports every rejection to onError while preserving the caller rejection', async () => {
  const object = {reason: 'unavailable'};
  const originalError = new Error('unavailable');
  const values: unknown[] = ['unavailable', object, undefined, originalError];
  const results = [];

  for (const value of values) {
    const session: ChatSession = {
      sessionId: 's1',
      userId: 'u1',
      entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
    };
    const received: Error[] = [];
    const orchestrator = createChatOrchestrator(
      createBedrockProvider({type: 'bedrock', modelId: 'unused', region: 'eu-central-1', maxTokens: 1}),
      new PromptBuilder({identity: 'test'}),
      undefined,
      {hooks: {
        beforeSession: async () => { throw value; },
        onError: async (_session, error) => { received.push(error); },
      }}
    );
    const outcome = await orchestrator.processMessage(session).then(
      () => ({rejected: false, value: undefined}),
      (error: unknown) => ({rejected: true, value: error})
    );
    results.push({
      rejected: outcome.rejected,
      original: Object.is(outcome.value, value),
      calls: received.length,
      isError: received[0] instanceof Error,
      preserved: value instanceof Error ? received[0] === value : Object.is(received[0]?.cause, value),
    });
  }

  expect(results).toEqual(values.map(() => ({rejected: true, original: true, calls: 1, isError: true, preserved: true})));
});
EOF
cat > .lore/dod.md <<'EOF'
# Definition of Done

> A rejection that is not an "'`Error` — a thrown string, a plain object, a value from a library that rejects with its own shape — bypasses `onError` entirely while still propagating to the caller.

**Strategy: `direct`** — The real orchestrator accepts lifecycle hooks and exposes `processMessage`; a rejecting hook exercises the same catch that handles provider failures.

## Done when these pass

- [ ] **reports every rejection to onError while preserving the caller rejection** — String, object and undefined rejections reach the hook as Errors with the original cause; Error instances and all caller rejections retain their identity.
  `src/orchestration/chatOrchestrator.acceptance.test.ts`

## Facets

- [ ] Call `onError` once for non-Error rejections with an Error carrying the original cause, and rethrow the original value.
- [ ] Preserve existing Error identity and existing tests.
- [ ] Replace the recorded flaw in the spec with the guarantee and document the consumer-facing change in the CHANGELOG.

## Out of scope

- Usage accounting across tool rounds and unrelated lifecycle changes.
EOF
